        let (paid, capacity) = result.unwrap();
        assert!(observed.allocated <= paid);
        assert!(capacity <= 2 * (depth + 1).max(4));
        clean(observed);
        let (exact, observed) = deep_probe(&program, depth, setup + paid);
        assert_eq!(exact.unwrap(), (paid, capacity));
