    };
    let body = ResolvedExpr {
        id: ExpressionId::new(function, "body.s1.value.s2.body.s1.value"),
        ty: ResolvedType::Usize,
        ownership: OwnershipMode::Value,
        kind: ResolvedExprKind::Usize(0),
        span,
    };
